helpers:
SET search_path=app,pg_catalog;
CREATE FUNCTION attempt(command text) RETURNS jsonb LANGUAGE plpgsql AS $try$
DECLARE state text; message text; detail text;
BEGIN
 EXECUTE command;
 RETURN jsonb_build_object('ok',true,'sqlstate','00000');
EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS state=RETURNED_SQLSTATE, message=MESSAGE_TEXT, detail=PG_EXCEPTION_DETAIL;
 RETURN jsonb_build_object('ok',false,'sqlstate',state,'message',message,'detail',detail);
END $try$;
CREATE FUNCTION capture() RETURNS jsonb LANGUAGE plpgsql AS $cap$
DECLARE rows jsonb:='{}'; probes jsonb:='{}'; tab record; cells jsonb;
BEGIN
 FOR tab IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname IN ('app','other') AND c.relkind IN ('r','p') AND c.relname IN ('p','p2','a','b') ORDER BY n.nspname,c.relname
 LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text),''[]''::jsonb) FROM %I.%I t',tab.nspname,tab.relname) INTO cells;
  rows:=rows||jsonb_build_object(tab.relname,cells);
  IF tab.relname IN ('p','p2') AND EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=format('%I.%I',tab.nspname,tab.relname)::regclass AND attname='d' AND NOT attisdropped) THEN
   EXECUTE format('SELECT jsonb_build_object(''rows'',count(*),''duplicate_key_groups'',(SELECT count(*) FROM (SELECT k,d FROM %I.%I GROUP BY k,d HAVING count(*)>1) duplicates)) FROM %I.%I',tab.nspname,tab.relname,tab.nspname,tab.relname) INTO cells;
   probes:=probes||jsonb_build_object(tab.relname,cells);
  END IF;
 END LOOP;
 RETURN jsonb_build_object('rows',rows,'tree_probes',probes,
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'schema',CASE WHEN n.nspname='app' THEN 's' ELSE 'm' END,'column',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END,'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'inherited',a.attinhcount,'local',a.attislocal,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum)
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname IN ('app','other') AND c.relname IN ('p','p2','a','b')),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',q.conname,'kind',q.contype,'definition',pg_get_constraintdef(q.oid,true),'local',q.conislocal,'inherited',q.coninhcount,'validated',q.convalidated,'parent',pq.conname) ORDER BY c.relname,q.conname)
 FROM pg_constraint q JOIN pg_class c ON c.oid=q.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_constraint pq ON pq.oid=q.conparentid WHERE n.nspname IN ('app','other') AND c.relname IN ('p','p2','a','b')),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',t.relname,'name',i.relname,'definition',pg_get_indexdef(i.oid),'unique',x.indisunique,'primary',x.indisprimary,'valid',x.indisvalid,'parent',pi.relname) ORDER BY t.relname,i.relname)
 FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace JOIN pg_class i ON i.oid=x.indexrelid LEFT JOIN pg_inherits h ON h.inhrelid=i.oid LEFT JOIN pg_class pi ON pi.oid=h.inhparent WHERE n.nspname IN ('app','other') AND t.relname IN ('p','p2','a','b')),
 'membership',(SELECT jsonb_agg(jsonb_build_object('child',c.relname,'parent',p.relname) ORDER BY c.relname,p.relname) FROM pg_inherits h JOIN pg_class c ON c.oid=h.inhrelid JOIN pg_class p ON p.oid=h.inhparent JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('app','other') AND c.relkind IN ('r','p')));
END $cap$;
CREATE FUNCTION probe(table_name text,key_value integer) RETURNS jsonb LANGUAGE plpgsql AS $probe$
DECLARE answer jsonb; state text; message text;
BEGIN
 EXECUTE format('INSERT INTO %s(k) VALUES(%s) RETURNING to_jsonb(%s.*)',table_name,key_value,table_name) INTO answer;
 RETURN jsonb_build_object('ok',true,'row',answer);
EXCEPTION WHEN OTHERS THEN
 GET STACKED DIAGNOSTICS state=RETURNED_SQLSTATE,message=MESSAGE_TEXT;
 RETURN jsonb_build_object('ok',false,'sqlstate',state,'message',message);
END $probe$;
